  "evidencias": [
    {
      "cita_literal_breve": "La alerta temprana se presenta sin demora indebida y, como máximo, en veinticuatro horas desde que se tiene constancia del incidente significativo.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "Cuando proceda, indica sospecha de acción ilícita o malintencionada y posibles repercusiones transfronterizas.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "La notificación del incidente ordinaria se presenta sin demora indebida y, como máximo, en setenta y dos horas desde esa constancia.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "Actualiza la alerta cuando proceda e incluye evaluación inicial de gravedad e impacto e indicadores de compromiso disponibles.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "El informe intermedio se presenta a petición del CSIRT o autoridad competente.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "El informe final ordinario debe presentarse a más tardar un mes después de la notificación del apartado b.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "Recoge descripción, gravedad e impacto, amenaza o causa probable, medidas paliativas y, cuando proceda, repercusiones transfronterizas.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "Los máximos temporales no eliminan la exigencia de actuar sin demora indebida.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000033-L000044"
    },
    {
      "cita_literal_breve": "Se contemplan notificaciones a CSIRT o autoridad y, cuando proceda, comunicaciones a destinatarios afectados.",
      "documento": "CYB-03",
